# -*- coding: utf-8 -*-
# Generates the Hindi Course B seed files and extends Hindi Course A (v43).
# Source of structure: CBSE Class 10 Hindi A (code 002) and Hindi B (code 085) syllabus 2026-27,
# uploaded by the founder. All questions are written in Devanagari, MCQ only, and start as
# needs_review (the subject is a pilot): a Hindi teacher must check every item before it is trusted.
# Run:  python3 packages/db/seed-generators/gen_hindi.py   (rewrites the JSON files in packages/db/seed/)
import json, os, sys

OUT = os.path.join(os.path.dirname(__file__), '..', 'seed')

def Q(skill, diff, prompt, answer, wrong, expl, tag='CONCEPT_CONFUSION'):
    opts = [answer] + list(wrong)
    assert len(opts) == 4 and len(set(opts)) == 4, (skill, prompt)
    return {'skill_slug': skill, 'difficulty': diff, 'question_type': 'mcq', 'prompt': prompt,
            'expected_answer': {'value': answer}, 'misconception_tags': [tag], 'options': opts, 'explanation': expl}

def rotate(q, k):
    """Move the correct answer to a different position so keys are not always first."""
    o = q['options']; k = k % 4
    q['options'] = o[k:] + o[:k]
    return q

def skill(slug, name, requires=None):
    return {'name': name, 'slug': slug, 'requires': requires or []}

def topic(slug, name, seq, skills):
    return {'name': name, 'slug': slug, 'sequence': seq, 'skills': skills}

def chapter(slug, name, seq, topics):
    return {'name': name, 'slug': slug, 'sequence': seq, 'topics': topics}

