B_QUESTIONS = B_GRAMMAR + B_TEXT_Q

def main():
    # --- Hindi A: remove lessons excluded from the 2026-27 exam, add the missing parts
    path = os.path.join(OUT, 'cbse-class10-hindi.json')
    a = json.load(open(path, encoding='utf-8'))
    EXCLUDED_TOPICS = {'stri-shiksha-kutark', 'kanyadaan', 'george-pancham-ki-naak'}
    for ch in a['chapters']:
        ch['topics'] = [t for t in ch['topics'] if t['slug'] not in EXCLUDED_TOPICS]
    a['chapters'] = [c for c in a['chapters'] if c['topics']]
    have = {c['slug'] for c in a['chapters']}
    for ch in A_NEW_CHAPTERS:
        if ch['slug'] not in have: a['chapters'].append(ch)
    a['subject']['description'] = 'CBSE Class 10 Hindi Course A (code 002), syllabus 2026-27: Kshitij Part 2 and Kritika Part 2 (excluded lessons removed), grammar, unseen passages and writing. AI-assisted content pending teacher review. Questions in Devanagari (older questions in Latin script).'
    json.dump(a, open(path, 'w', encoding='utf-8'), ensure_ascii=False, indent=1)

    dpath = os.path.join(OUT, 'cbse-class10-hindi-diagnostic.json')
    da = json.load(open(dpath, encoding='utf-8'))
    drop = {'explain-stri-shiksha-argument', 'explain-kanyadaan-message', 'explain-george-pancham-satire'}
    da['questions'] = [q for q in da['questions'] if q['skill_slug'] not in drop and not q['skill_slug'].startswith('ha-')]
    for i, q in enumerate(A_NEW_QUESTIONS): da['questions'].append(rotate(q, i))
    json.dump(da, open(dpath, 'w', encoding='utf-8'), ensure_ascii=False, indent=1)

    # --- Hindi B
    b = {'curriculum': a['curriculum'],
         'subject': {'name': 'Hindi Course B', 'slug': 'hindi-b', 'status': 'pilot',
                     'description': 'CBSE Class 10 Hindi Course B (code 085), syllabus 2026-27: Sparsh Part 2 (Bihari dohe, Madhur madhur mere deepak jal and Girgit excluded) and Sanchayan Part 2, grammar, unseen passages and writing. AI-assisted content pending teacher review. Questions in Devanagari.'},
         'chapters': B_CHAPTERS}
    json.dump(b, open(os.path.join(OUT, 'cbse-class10-hindi-b.json'), 'w', encoding='utf-8'), ensure_ascii=False, indent=1)
    bq = {'subject_slug': 'hindi-b', 'questions': [rotate(q, i) for i, q in enumerate(B_QUESTIONS)]}
    json.dump(bq, open(os.path.join(OUT, 'cbse-class10-hindi-b-diagnostic.json'), 'w', encoding='utf-8'), ensure_ascii=False, indent=1)

    # --- self-checks
    for name, data, qs in (('A', a, da['questions']), ('B', b, bq['questions'])):
        skills = {s['slug'] for c in data['chapters'] for t in c['topics'] for s in t['skills']}
        for q in qs:
            if q['skill_slug'] in skills or q['skill_slug'] in ('identify-netaji-ka-chashma-subject',): pass
        missing = [q['skill_slug'] for q in qs if q['skill_slug'] not in skills]
        assert not missing, (name, missing[:5])
        covered = {q['skill_slug'] for q in qs}
        print(name, 'skills', len(skills), 'questions', len(qs), 'skills without a question:', sorted(skills - covered))
        for q in qs:
            assert q['expected_answer']['value'] in q['options'] and len(set(q['options'])) == 4

if __name__ == '__main__':
    main()
